/**
 * Slack auth helpers — AuthContext builders for thread-scoped sessions.
 */
import { samePrincipal } from "../../internal/auth.js";
import { slackThreadKey } from "../../internal/slack-thread-key.js";
/**
 * Build a Slack session principal.
 *
 * - `"thread"` (default): any participant can continue.
 * - `"author"`: only the starter (`…:{userId}`), same shape approvals already honor.
 */
export function buildSlackAuthContext(args) {
    const team = args.teamId ?? "unknown";
    const respondTo = args.respondTo ?? "thread";
    // One person owns a DM, so the principal covers the whole DM even when the
    // selector gives each DM thread its own session.
    const conversation = slackThreadKey(args.channelId, args.threadTs, "whole-dm");
    const base = `slack:${team}:${conversation}`;
    const authorScoped = respondTo === "author" && args.userId !== undefined && args.userId !== "";
    const principalId = authorScoped ? `${base}:${args.userId}` : base;
    const attributes = {
        channel_id: args.channelId,
        thread_ts: args.threadTs,
    };
    if (args.teamId !== undefined) {
        attributes.team_id = args.teamId;
    }
    if (args.userId !== undefined) {
        attributes.user_id = args.userId;
    }
    if (args.userName !== undefined) {
        attributes.user_name = args.userName;
    }
    if (args.isBot === true) {
        attributes.author_type = "bot";
    }
    if (args.engagement !== undefined) {
        attributes.engagement = args.engagement;
    }
    return {
        authenticator: "slack",
        principalId,
        principalType: "user",
        attributes,
    };
}
/**
 * Auth for a Slack user clicking an interactive Approve/Deny button.
 * Uses the clicker's identity for {@link SessionEngine.resolveApproval},
 * not the stored session principal (which would bypass ownership checks).
 */
export function buildSlackInteractiveApprovalAuth(args) {
    const clickerAuth = buildSlackAuthContext({
        channelId: args.channelId,
        threadTs: args.threadTs,
        teamId: args.teamId,
        userId: args.clickingUserId,
    });
    if (samePrincipal(args.sessionAuth, clickerAuth)) {
        return clickerAuth;
    }
    const userSuffix = `:${args.clickingUserId}`;
    if (args.clickingUserId !== "" && args.sessionAuth.principalId.endsWith(userSuffix)) {
        return {
            ...clickerAuth,
            principalId: args.sessionAuth.principalId,
        };
    }
    return clickerAuth;
}
/**
 * Default auth for an `onBlockAction` dispatch: the click's thread-scoped
 * principal with the clicker in attributes, so replies in the same thread
 * continue the session and the clicker is the attributable user.
 */
export function blockActionAuth(action) {
    return buildSlackAuthContext({
        channelId: action.channelId,
        threadTs: action.threadTs,
        teamId: action.teamId,
        userId: action.userId,
        userName: action.userName,
    });
}
export function defaultSlackAuth(message, ctx, options) {
    if (message.author === undefined) {
        return null;
    }
    return buildSlackAuthContext({
        channelId: ctx.slack.channelId,
        threadTs: ctx.slack.threadTs,
        teamId: message.teamId,
        userId: message.author.userId,
        userName: message.author.userName,
        isBot: message.author.isBot,
        engagement: options?.engagement,
        respondTo: options?.respondTo,
    });
}
